COMMON = '''Use case: ui-mockup
Asset type: proposed LetBuyy design-system Storybook board, not a production screenshot.
Create one exceptionally crisp wide landscape UI presentation image, target 3840x2160, restrained premium enterprise editorial design. Exact board title at top: "{number} / {title}". Subtitle: "LetBuyy | Proposed responsive system".
Every image MUST contain three clearly labeled complete responsive specimens in the main row: "Desktop · 1440", "Tablet · 768", "Mobile · 390". These labels denote design viewport widths in CSS px, NOT image raster dimensions. Desktop occupies about 52% of main row width, tablet 28%, mobile20%; show flat screen rectangles, no angled devices. Preserve enough height for usable form/table examples; clean lower strip of 2-4 small clearly labeled state insets. No overlapping frames, cropped mobile, unreadable microscopic paragraphs or giant decorative whitespace. Contextual annotations outside specimens only.
Visual identity: deep-plum rail/header #1E1A2D; filled primary #2C2642; hover #362C58; pressed #181524; links #523F97; focus #6C54C4 with white separation on dark; selection wash #E7E3F7; lavender rail secondary #C9BFED; canvas #F6F7F9; white work cards and inputs; primary text #111827; secondary #6B7280 with full opacity; quiet dividers #E5E7EB; meaningful control boundary #8F88A9. Green/amber/red/blue keep semantic labels, not all purple. No neon, broad purple glow, excessive gradients, glassmorphism or dark content cards. White work surfaces dominate, plum is deliberate.
Typography: Geist-like clean sans, sentence case, 24/32 task headings weight600, 14/20 body,13/18 table text,12/16 supporting captions. Task spacing 8/12/16/24/32px rhythm. Controls radius8, cards/dialogs12, major workspace16; pills only suitable chips. Desktop 36/40px controls, mobile44px comfortable targets. Subtle elevation only on overlays. Consistent Lucide-like line icons16inline/20navigation. Use the existing brand word "LetBuyy", no invented logo mark. Fictional Demo Store and illustrative data only. Do not copy Shopify branding or its layout verbatim. No storefront palette overwrite. Text must be concise, correctly spelled and legible. No claims of shipped or tested behavior.
Board content and responsive transformations:
{scene}
Footer small but readable: "Proposed mockup · desktop / tablet / mobile · exact behavior in companion specification".
'''

ROOT.mkdir(parents=True, exist_ok=True)
(ROOT/'prompts').mkdir(exist_ok=True)
(ROOT/'images').mkdir(exist_ok=True)
boards=[]
existing = {}
if (ROOT/'mockup-manifest.json').exists():
    existing = {b['id']: b for b in json.loads((ROOT/'mockup-manifest.json').read_text())['boards']}
for i,(key,title,patterns,scene,states) in enumerate(BOARDS,1):
    prompt=COMMON.format(number=f'{i:02}',title=title,scene=scene)
    (ROOT/'prompts'/f'{key}.txt').write_text(prompt)
    board = {'id':key,'title':title,'status':'planned','viewports_css_px':[1440,768,390],
        'image':f'images/{key}.png','prompt':f'prompts/{key}.txt',
        'canonical_patterns':[f'PAT-{p:02}' for p in patterns], 'required_states':states,
        'generation_mode':'built-in image_gen','raster_is_normative':False}
    for field in ('status', 'raster_dimensions', 'source_image', 'generation_prompt', 'review_notes', 'revision_history'):
        if field in existing.get(key, {}):
            board[field] = existing[key][field]
    boards.append(board)
manifest={'date':'2026-10-22','source_head':'85aac99043d8dc10469e12cbb810609a3b6f1b0d',
 'scope':'Mockups precede implementation; existing architecture and component owners retained',
 'kind':'Generated visual proposals, not shipped UI, real Storybook stories, screenshots or behavioral tests',
 'token_authority':'packages/typescript/ui/src/tokens.ts',
 'exact_specification':'../03_PREMIUM_PURPLE_SYSTEM.md', 'boards':boards}
(ROOT/'mockup-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(f'Wrote {len(boards)} briefs. Canonical families covered: {len(set(p for b in boards for p in b["canonical_patterns"]))}/32')
